UPDATE templates
SET title = 'Sprint-Planung',
    description = 'Für die Sprint-Planung im Entwicklungsteam. Der Schwerpunkt liegt auf Ziel, Kapazität und Definition von fertig: was der Sprint erreichen soll, wer wie viel Zeit hat und woran „fertig“ gemessen wird.',
    sections_json = '[{"title": "TL;DR", "description": "Die drei bis fünf wichtigsten Punkte, Entscheidungen und Aufgaben zuerst, für jemanden mit dreißig Sekunden."}, {"title": "Sprint-Ziel", "description": "Das Hauptziel dieses Sprints in einem oder zwei Stichpunkten, so wie es ausgesprochen wurde."}, {"title": "Sprint-Backlog", "description": "Die Stories und Arbeitspakete, auf die sich das Team festgelegt hat, mit ihren Schätzungen, wo welche fielen."}, {"title": "Kapazität und Verfügbarkeit", "description": "Wer wie viel Zeit hat, Urlaube, Abwesenheiten, genannte Zahlen."}, {"title": "Abhängigkeiten und Risiken", "description": "Was von außen kommen muss und was schiefgehen kann, ein Stichpunkt je Punkt."}, {"title": "Definition von fertig", "description": "Woran „fertig“ gemessen wird: Abnahmekriterien und Standards, wie sie besprochen wurden."}, {"title": "Aufgaben", "description": "Als Markdown-TABELLE mit genau diesen Spalten:\n\n| Aufgabe | Wer | Bis |\n|---|---|---|\n\nEine Zeile je Aufgabe. Schreib nie ein Pipe-Zeichen in eine Tabellenzelle, das bricht die Tabelle; formulier um oder ersetz es durch ein Komma."}, {"title": "Offene Fragen", "description": "Was angesprochen, aber nicht geklärt wurde, dazu jede Stelle, an der das Transkript widersprüchlich oder unverständlich war. Ein Stichpunkt je Frage."}, {"title": "Zahlen und Namen zur Gegenprüfung", "description": "Alle Zahlen, Beträge, Termine und Eigennamen aus dem Gespräch, so wie sie im Transkript stehen, als kurze Liste. Sie dienen dem Gegenprüfen, weil sich die Transkription verhören kann; nichts ergänzen, nichts runden. Schreibt das Transkript denselben Namen verschieden, nenn die Varianten nebeneinander, statt dich für eine zu entscheiden."}]'
WHERE id = 'default-sprint-planning'
  AND title = 'Sprint Planning'
  AND description = 'For planning development sprints and setting team goals'
  AND sections_json = '[{"title":"Sprint Goal","description":"What is the main objective for this sprint?"},{"title":"Sprint Backlog","description":"Stories and tasks committed for the sprint"},{"title":"Capacity & Availability","description":"Team availability and capacity estimates"},{"title":"Dependencies & Risks","description":"External dependencies and potential risks"},{"title":"Definition of Done","description":"Acceptance criteria and completion standards"}]';


UPDATE templates
SET title = 'Sprint-Retrospektive',
    description = 'Für den Rückblick am Sprint-Ende. Der Schwerpunkt liegt auf dem Dreischritt: was gut lief, was nicht lief, was daraus gelernt wurde.',
    sections_json = '[{"title": "TL;DR", "description": "Die drei bis fünf wichtigsten Punkte, Entscheidungen und Aufgaben zuerst, für jemanden mit dreißig Sekunden."}, {"title": "Was gut lief", "description": "Was funktioniert hat, ein Stichpunkt je Sache, mit dem konkreten Beleg aus dem Sprint."}, {"title": "Was nicht gut lief", "description": "Probleme und Reibung, ein Stichpunkt je Sache. Benenn sie so, wie sie im Gespräch benannt wurden, ohne sie zu entschärfen."}, {"title": "Was wir gelernt haben", "description": "Die Einsichten, die das Team ausgesprochen hat, getrennt von den Maßnahmen darunter."}, {"title": "Aufgaben", "description": "Als Markdown-TABELLE mit genau diesen Spalten:\n\n| Aufgabe | Wer | Bis |\n|---|---|---|\n\nEine Zeile je Aufgabe. Schreib nie ein Pipe-Zeichen in eine Tabellenzelle, das bricht die Tabelle; formulier um oder ersetz es durch ein Komma."}, {"title": "Offene Fragen", "description": "Was angesprochen, aber nicht geklärt wurde, dazu jede Stelle, an der das Transkript widersprüchlich oder unverständlich war. Ein Stichpunkt je Frage."}, {"title": "Zahlen und Namen zur Gegenprüfung", "description": "Alle Zahlen, Beträge, Termine und Eigennamen aus dem Gespräch, so wie sie im Transkript stehen, als kurze Liste. Sie dienen dem Gegenprüfen, weil sich die Transkription verhören kann; nichts ergänzen, nichts runden. Schreibt das Transkript denselben Namen verschieden, nenn die Varianten nebeneinander, statt dich für eine zu entscheiden."}]'
WHERE id = 'default-sprint-retrospective'
  AND title = 'Sprint Retrospective'
  AND description = 'For reflecting on sprints to continuously improve team processes and collaboration'
  AND sections_json = '[{"title":"What Went Well","description":"Celebrate wins and positive outcomes"},{"title":"What Didn''t Go Well","description":"Identify challenges and problems"},{"title":"What We Learned","description":"Key insights and takeaways"},{"title":"Action Items","description":"Concrete steps for improvement"}]';
